namespace sv_15fc356a2b8148ec874af89b457d38e4.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped (per-circuit) service that holds theme state and notifies
/// subscribers when it changes. Because it is Scoped, each user's
/// SignalR circuit gets its own independent instance.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public ThemeMode Theme => _theme;
    public string AccentColor => _accentColor;

    /// <summary>Fired whenever Theme or AccentColor changes.</summary>
    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        if (_theme == theme) return;
        _theme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (string.Equals(_accentColor, color, StringComparison.OrdinalIgnoreCase)) return;
        _accentColor = color;
        OnChange?.Invoke();
    }

    public void SetAll(ThemeMode theme, string accentColor)
    {
        bool changed = _theme != theme
            || !string.Equals(_accentColor, accentColor, StringComparison.OrdinalIgnoreCase);
        _theme = theme;
        _accentColor = accentColor;
        if (changed) OnChange?.Invoke();
    }
}

// Theme interop module — applies theme state to the DOM so that
// both static (SSR) and interactive elements reflect the current theme.

export function applyTheme(themeMode, accentColor) {
    const root = document.documentElement;

    // Resolve effective theme (light/dark) when mode is "system"
    let effective = themeMode.toLowerCase();
    if (effective === "system") {
        effective = window.matchMedia("(prefers-color-scheme: dark)").matches
            ? "dark"
            : "light";
    }

    // Bootstrap 5.3+ supports data-bs-theme for light/dark switching
    root.setAttribute("data-bs-theme", effective);

    // Also set a plain attribute for custom CSS selectors
    root.setAttribute("data-theme", effective);

    // Apply accent color as a CSS custom property
    root.style.setProperty("--app-accent-color", accentColor);
}

// Listen for OS theme changes so "System" mode reacts in real time
let _currentMode = "system";
let _currentAccent = "#0d6efd";

window.matchMedia("(prefers-color-scheme: dark)")
    .addEventListener("change", () => {
        if (_currentMode === "system") {
            applyTheme(_currentMode, _currentAccent);
        }
    });

export function trackTheme(themeMode, accentColor) {
    _currentMode = themeMode.toLowerCase();
    _currentAccent = accentColor;
    applyTheme(themeMode, accentColor);
}

@*
    Interactive island placed inside the static MainLayout.
    It bridges ThemeService (C# events) → JS (DOM updates) so that
    the entire page — including static markup — reflects the theme.
*@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

@code {
    private IJSObjectReference? _module;

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./js/theme.js");
            await ApplyCurrentTheme();
        }
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyCurrentTheme();
            StateHasChanged();
        });
    }

    private async Task ApplyCurrentTheme()
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync("trackTheme",
                ThemeService.Theme.ToString(), ThemeService.AccentColor);
        }
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@*
    Small interactive component shown in the layout header.
    Displays the current theme and lets the user cycle through modes.
*@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator d-inline-flex align-items-center gap-1"
      role="button"
      title="Click to change theme"
      @onclick="CycleTheme"
      style="cursor:pointer; color: var(--app-accent-color, inherit);">
    @Icon @ThemeService.Theme.ToString()
</span>

@code {
    private string Icon => ThemeService.Theme switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        _                => "💻"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChange;
    }

    private void CycleTheme()
    {
        var next = ThemeService.Theme switch
        {
            ThemeMode.Light  => ThemeMode.Dark,
            ThemeMode.Dark   => ThemeMode.System,
            _                => ThemeMode.Light
        };
        ThemeService.SetTheme(next);
    }

    private async void HandleChange()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleChange;
    }
}

@*
    Full preferences panel for the /settings page.
    Changes here propagate through ThemeService → ThemeProvider → JS
    so every component (including the header indicator) updates immediately.
*@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<div class="card p-4" style="max-width: 480px;">
    <h4>Appearance</h4>

    <div class="mb-3">
        <label class="form-label fw-semibold">Theme Mode</label>
        <div class="btn-group d-flex" role="group">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                var isActive = mode == ThemeService.Theme;
                <button type="button"
                        class="btn @(isActive ? "btn-primary" : "btn-outline-secondary")"
                        @onclick="() => ThemeService.SetTheme(mode)">
                    @mode.ToString()
                </button>
            }
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label fw-semibold" for="accentColor">Accent Color</label>
        <div class="d-flex align-items-center gap-3">
            <input id="accentColor"
                   type="color"
                   class="form-control form-control-color"
                   value="@ThemeService.AccentColor"
                   @onchange="OnAccentChanged" />
            <span class="text-muted">@ThemeService.AccentColor</span>
        </div>
    </div>

    <div class="border rounded p-3 mt-2"
         style="background-color: var(--app-accent-color); color: #fff;">
        Preview: this box uses your accent color.
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChange;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    private async void HandleChange()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleChange;
    }
}

